<script>
 import {keyboard} from '../lib/shortcuts.ts';
 import {onDestroy,tick} from 'svelte';import {isEditDoubleClick} from '../grid-click';import ProjectPeek from './ProjectPeek.svelte';
 import {Plus,FolderOpen,ArrowLeft,Check,Trash2,RotateCcw,Pencil,X,Minus,ZoomIn} from 'lucide-svelte';import {studio,current,assets,selectProject,select,toggle,run,updateProject,notify,save,trashSelected,importImages,clearSelection,liveAssets,refresh} from '../studio.svelte';import {api,bytes,stored,persist} from '../api';
 let name=$state(''),creating=$state(false),renaming=$state(false),query=$state(''),covers=$state({}),renameId=$state('');let filtered=$derived(assets().filter(a=>a.name.toLowerCase().includes(query.trim().toLowerCase())));let allVisibleSelected=$derived(filtered.length>0&&filtered.every(a=>studio.selected.includes(a.id)));
 let projectZoom=$state(stored('project-grid-zoom',1)),imageZoom=$state(stored('image-grid-zoom',1)),peek=$state(null),peekComponent=$state(),library;let openTimer;
 let zoom=$derived(studio.view==='projects'?projectZoom:imageZoom);
 function changeZoom(value){const next=Math.min(1.8,Math.max(.6,Math.round(value*100)/100));if(studio.view==='projects'){projectZoom=next;persist('project-grid-zoom',next);}else{imageZoom=next;persist('image-grid-zoom',next);}}
 function zoomWheel(e){if(!e.ctrlKey)return;e.preventDefault();e.stopPropagation();changeZoom(zoom*Math.exp(-e.deltaY*(e.deltaMode===1?20:1)*.0015));}
 function zoomArea(node){const handler=e=>zoomWheel(e);node.addEventListener('wheel',handler,{passive:false});return{destroy(){node.removeEventListener('wheel',handler);}};}
 function hidePeek(){clearTimeout(openTimer);peek=null;}
 function leavePeek(e){clearTimeout(openTimer);if(e?.type==='blur'&&!e.relatedTarget?.closest('.project-peek'))hidePeek();}
 function schedulePeek(project,anchor){clearTimeout(openTimer);if(peek?.project.id===project.id)return;openTimer=setTimeout(()=>peek={project,anchor},170);}
 async function cardWheel(e,project){if(e.ctrlKey)return; e.preventDefault();e.stopPropagation();clearTimeout(openTimer);if(peek?.project.id!==project.id)peek={project,anchor:e.currentTarget.closest('.project-card')};await tick();peekComponent?.scrollBy(e.deltaY*(e.deltaMode===1?20:1));}
 function openPreview(pid,id){hidePeek();selectProject(pid);select(id);}
 onDestroy(()=>{clearTimeout(openTimer);});
 let lastImageClick=null;
 function imageClick(e,id){
  const click={id,time:e.timeStamp,detail:e.detail,x:e.clientX,y:e.clientY};
  const edit=isEditDoubleClick(lastImageClick,click);
  lastImageClick=e.detail===1?click:null;
  toggle(id);
  if(edit)openAsset(id);
 }
 async function removeProject(p){const dataRoot=studio.dataRoot;hidePeek();await run('删除项目',async()=>{await save(p.assets.map(a=>a.id),p.id);await api('project_delete',{projectId:p.id});if(studio.pid===p.id){studio.pid='';studio.aid='';}await refresh();studio.view='projects';notify('项目已移入回收目录：'+p.name,null,{open:true,receiptAction:{kind:'project-delete',projectId:p.id,dataRoot}});});}
 function openAsset(id){if(studio.trash)return;select(id);studio.view='canvas';}
 function back(){studio.trash=false;clearSelection();if(!liveAssets().some(a=>a.id===studio.aid))select(liveAssets()[0]?.id||'');studio.view='canvas';}
 function editName(project){creating=false;renaming=true;renameId=project.id;name=project.name;}
 function selectVisible(){const ids=filtered.map(a=>a.id);studio.selected=allVisibleSelected?studio.selected.filter(id=>!ids.includes(id)):[...new Set([...studio.selected,...ids])];studio.batchScope='auto';}
 async function create(){if(!name.trim())return;await run("正在创建项目",async()=>{const p=await api('project_create',{name:name.trim()});updateProject(p);selectProject(p.id);name='';creating=false;});}
 async function rename(){if(!name.trim())return;await run("正在重命名",async()=>{updateProject(await api('project_rename',{projectId:renameId||studio.pid,name:name.trim()}));renaming=false;name='';});}
 async function restoreOne(id){studio.selected=[id];await trashSelected(true);}
</script>
<div bind:this={library} class="library" inert={!!studio.busy} use:zoomArea onscroll={hidePeek} style:--project-card-size={`${230*projectZoom}px`} style:--project-stack-height={`${180*projectZoom}px`} style:--image-card-size={`${170*imageZoom}px`} style:--image-thumb-height={`${165*imageZoom}px`}><div class="library-heading"><div><button class="text-button" onclick={back}><ArrowLeft size={14}/>返回画布</button><h1>{studio.view==='projects'?"项目":studio.trash?"回收站":current()?.name}</h1></div><div class="button-row"><div class="grid-zoom" aria-label="预览大小"><button aria-label="缩小预览" title="缩小预览" disabled={zoom<=.6} onclick={()=>changeZoom(zoom-.1)}><Minus size={13}/></button><button class="zoom-readout" aria-label="恢复预览大小" title="Ctrl 加滚轮缩放，点击恢复 100%" onclick={()=>changeZoom(1)}>{Math.round(zoom*100)}%</button><button aria-label="放大预览" title="放大预览" disabled={zoom>=1.8} onclick={()=>changeZoom(zoom+.1)}><ZoomIn size={13}/></button></div>{#if studio.view==='projects'}<button class="primary" onclick={()=>{creating=true;renaming=false;name='';}}><Plus size={15}/>新建项目</button>{:else}<button aria-label="重命名项目" title="重命名项目" onclick={()=>editName(current())}><Pencil size={16}/></button><button class="line-button" onclick={()=>importImages(true)}><FolderOpen size={15}/>文件夹</button><button class="primary" onclick={()=>importImages(false)}><Plus size={15}/>导入</button>{/if}</div></div>
{#if creating||renaming}<form class="name-form" onsubmit={e=>{e.preventDefault();creating?create():rename();}}><input aria-label="项目名称" bind:value={name} placeholder="项目名称" required maxlength="120"/><button class="primary" disabled={!name.trim()} type="submit">{creating?"创建":"重命名"}</button><button type="button" onclick={()=>{creating=false;renaming=false;}}>取消</button></form>{/if}
{#if studio.view==='projects'}<div class="project-grid">{#if !studio.projects.length}<div class="empty"><FolderOpen size={36}/><h2>暂无项目</h2><p>点击右上角“新建项目”，或返回素材库导入图片。</p></div>{/if}{#each studio.projects as project}<article class="project-card" onpointerenter={e=>{if(e.pointerType!=='touch')schedulePeek(project,e.currentTarget);}} onpointerleave={leavePeek}><button class="project-open" onfocus={e=>schedulePeek(project,e.currentTarget.closest('.project-card'))} onblur={leavePeek} oncontextmenu={e=>{e.preventDefault();editName(project);}} onwheel={e=>cardWheel(e,project)} onclick={()=>{hidePeek();selectProject(project.id);}}><div class="project-stack">{#each [...project.assets.filter(a=>!a.trashed),...project.assets.filter(a=>!a.trashed)].slice(covers[project.id]||0,(covers[project.id]||0)+Math.min(3,project.assets.filter(a=>!a.trashed).length)).reverse() as a,i}<img src={studio.thumbs[a.id]} alt="" style:transform={`rotate(${(i-1)*7}deg) translateX(${(i-1)*9}px)`}/>{/each}{#if !project.assets.some(a=>!a.trashed)}<FolderOpen size={36}/>{/if}</div><div><h2>{project.name}</h2><span>{project.assets.filter(a=>!a.trashed).length} 张图片</span></div></button><button class="project-delete" aria-label={`删除项目 ${project.name}`} title="删除项目" onclick={()=>removeProject(project)}><Trash2 size={15}/></button><button class="project-rename" aria-label={`Rename ${project.name}`} title="重命名项目" onclick={()=>editName(project)}><Pencil size={15}/></button></article>{/each}</div>
{:else}<div class="library-toolbar"><div class="segmented"><button class:active={!studio.trash} onclick={()=>{studio.trash=false;clearSelection();query='';}}>图片</button><button class:active={studio.trash} onclick={()=>{studio.trash=true;clearSelection();query='';}}>回收站</button></div><input class="search" aria-label="搜索图片" bind:value={query} placeholder="搜索图片"/><button class="text-button" disabled={!filtered.length} onclick={selectVisible}>{allVisibleSelected?"取消当前结果的勾选":query.trim()?"勾选搜索结果":"全选"}</button>{#if studio.selected.length}<button class="line-button" onclick={()=>trashSelected(studio.trash)}>{#if studio.trash}<RotateCcw size={14}/>恢复 {studio.selected.length}{:else}<Trash2 size={14}/>回收站 {studio.selected.length}{/if}</button><button aria-label="取消全部勾选" title="取消全部勾选" onclick={clearSelection}><X size={14}/></button>{/if}</div><div class="image-grid">{#each filtered as a}<article class:selected={studio.selected.includes(a.id)}><button class="image-open" onclick={e=>imageClick(e,a.id)} use:keyboard={{keydown: e=>{if(e.key==='Enter'){e.preventDefault();openAsset(a.id);}}}} aria-label={`Select ${a.name}`} aria-pressed={studio.selected.includes(a.id)} title={studio.trash?"单击勾选或取消":"单击勾选或取消，快速双击进入编辑"}><img src={studio.thumbs[a.id]} alt={a.name} loading="lazy"/></button><button class="image-check" aria-label={`Select ${a.name}`} aria-pressed={studio.selected.includes(a.id)} onclick={()=>toggle(a.id)}>{#if studio.selected.includes(a.id)}<Check size={12}/>{/if}</button><div><b>{a.name}</b><small>{a.width} × {a.height}<span>{bytes(a.bytes)}</span></small>{#if studio.trash}<button class="text-button" onclick={()=>restoreOne(a.id)}><RotateCcw size={13}/>恢复</button>{/if}</div></article>{/each}</div>{#if !filtered.length}<div class="empty"><FolderOpen size={36}/><h2>{query.trim()?"没有符合条件的图片":studio.trash?"回收站为空":"暂无图片"}</h2>{#if query.trim()}<button class="line-button" onclick={()=>query=''}>清除搜索</button>{:else if !studio.trash}<button class="primary" onclick={()=>importImages(false)}>导入图片</button>{/if}</div>{/if}{/if}</div>
{#if peek&&studio.view==='projects'}<ProjectPeek bind:this={peekComponent} project={peek.project} thumbs={studio.thumbs} anchor={peek.anchor} onselect={openPreview} onclose={hidePeek} onzoom={zoomWheel}/>{/if}
